import styled from '@emotion/styled';

import { Body } from '../organisms/Drawer/Drawer.styles';

export const StyledCopilotBody = styled(Body)`
  position: relative;
  display: flex;
  flex-direction: row;
  flex: 1;
  min-height: 0;
  padding: 0;
  overflow: hidden;
  box-sizing: border-box;
`;

export const StyledSidebarWrapper = styled.div`
  display: flex;
  flex-shrink: 0;
  min-height: 0;
`;

export const StyledMainContentWrapper = styled.div`
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
`;
